        case 'CRNRSTN_PHP':
            // '.php' => 'CRNRSTN_PHP',

            // @define('CRNRSTN_PHP', (int) _crnrstn_int_return('CRNRSTN_PHP'));

            $R_meta['family']                 = 'UNCLASSIFIED_FILE_TYPE';
            $R_meta[$R_int_flag['R_integer']] = $R_int_flag['CRNRSTN_PHP'];
